const CAP = 2; const buf = [];
function put(v) { if (buf.length < CAP) { buf.push(v); return "ok"; } return "blocked"; }
function take() { return buf.length ? buf.shift() : "empty"; }
const ev = [];
for (let i = 1; i <= 6; i++) ev.push(`put ${i}: ${put(i)} (buf=[${buf}])`);
for (let i = 0; i < 3; i++) ev.push(`take: ${take()} (buf=[${buf}])`);
for (let i = 7; i <= 8; i++) ev.push(`put ${i}: ${put(i)} (buf=[${buf}])`);
console.log(ev.join("\n"));
